local x=np.astype(np.arange(12,"int64"):reshape({2,3,1,2}),"bool")
local before=x:tolist()
local y=r:permuted(x,-1,x)
deep(y.dtype,"bool","42/(2, 3, 1, 2)/bool/plain/-1/out_same dtype")
deep(y:tolist(),{{{{true,false}},{{true,true}},{{true,true}}},{{{true,true}},{{true,true}},{{true,true}}}},"42/(2, 3, 1, 2)/bool/plain/-1/out_same values")
deep(x:tolist(),{{{{true,false}},{{true,true}},{{true,true}}},{{{true,true}},{{true,true}},{{true,true}}}},"42/(2, 3, 1, 2)/bool/plain/-1/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"b286b60e1600888d","42/(2, 3, 1, 2)/bool/plain/-1/out_same pcg")
cases=cases+1; end
